['pointerup','pointercancel','lostpointercapture'].forEach(ev=>joystick.addEventListener(ev,releaseStick));joystick.addEventListener('contextmenu',e=>e.preventDefault());
function pollGamepad(){padMove=0;padJump=false;padFire=false;let pad;try{pad=Array.from(navigator.getGamepads?.()||[]).find(p=>p&&p.connected)}catch{}if(!pad){padPause=false;return}const pressed=i=>!!pad.buttons[i]?.pressed;const a=pad.axes[0]||0;padMove=pressed(14)?-1:pressed(15)?1:Math.abs(a)>.2?Math.sign(a)*(Math.abs(a)-.2)/.8:0;padJump=pressed(0);padFire=pressed(1)||pressed(2)||pressed(7);const pauseNow=pressed(9);if(pauseNow&&!padPause&&mode==='play')pause();padPause=pauseNow;}
window.addEventListener('gamepadconnected',()=>{if(mode==='play')toast('Controle conectado! A / ✕ pula; B / ○ dispara flores!');});
function damageBoss(amount){const b=state.boss;if(!b||b.hp<=0||b.inv>0)return false;b.hp=Math.max(0,b.hp-amount);b.inv=.35;burst(b.x+30,b.y+20,'#efc5e3',15);tone(260,.14);if(b.hp===0){state.darkShots=[];b.casting=false;burst(b.x+30,b.y,'#ffdd8a',35);toast('O guardião foi libertado! Vá até o portal.')}return true;}
function castShadow(b,p){if(state.darkShots.length>=12)return;const x=b.x+b.w/2,y=b.y+34,angle=Math.atan2(p.y+p.h/2-y,p.x+p.w/2-x),speed=b.hp<=2?175:145;for(const spread of b.hp<=2?[-.22,0,.22]:[0]){if(state.darkShots.length>=12)break;state.darkShots.push({x:x-8,y:y-8,w:16,h:16,vx:Math.cos(angle+spread)*speed,vy:Math.sin(angle+spread)*speed,life:4.5})}tone(145,.2,'triangle',.045);}
function updateCombat(dt){const s=state,p=s.p;s.fireCooldown=Math.max(0,s.fireCooldown-dt);if((input.fire||padFire)&&s.fireCooldown<=0&&s.flowers.length<4){s.flowers.push({x:p.x+p.w/2+p.face*21-8,y:p.y+22,w:16,h:16,vx:p.face*410,vy:-25,life:1.25});s.fireCooldown=.38;tone(840,.07,'triangle',.025)}
 for(const f of s.flowers){f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=55*dt;f.life-=dt;for(const e of s.enemies){if(f.life>0&&!e.dead&&overlap(f,e)){e.dead=true;f.life=0;burst(e.x+15,e.y+12,'#f2b5d6');tone(350,.08)}}if(f.life>0&&s.boss?.hp>0&&overlap(f,s.boss)){damageBoss(.5);f.life=0}if(s.platforms.some(b=>overlap(f,b)))f.life=0;}
 s.flowers=s.flowers.filter(f=>f.life>0&&f.x>0&&f.x<worlds[s.index].length+100);
 for(const shot of s.darkShots){shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;shot.life-=dt;if(overlap(shot,p)){shot.life=0;if(p.inv<=0){hit();return}}}
 s.darkShots=s.darkShots.filter(f=>f.life>0&&f.y>-50&&f.y<H+50);}
function step(dt){if(mode!=='play'||!state)return;let s=state,p=s.p,w=worlds[s.index];s.elapsed+=dt;s.time-=dt;s.toast-=dt;if(s.toast<=0)$('#toast').style.display='none';if(s.time<=0){loseLife();return}p.inv=Math.max(0,p.inv-dt);p.coyote=p.ground?.12:Math.max(0,p.coyote-dt);p.buffer=Math.max(0,p.buffer-dt);const jumping=input.jump||padJump;if(jumping&&!wasJump)p.buffer=.16;wasJump=jumping;if(p.buffer>0&&p.coyote>0){p.vy=-JUMP;p.ground=false;p.coyote=0;p.buffer=0;tone(510,.1)}if(!jumping&&p.vy<-260)p.vy+=G*dt*.75;
 const keyboardMove=Number(input.right)-Number(input.left);p.vx=(keyboardMove||input.axis||padMove)*SPEED;if(p.vx)p.face=p.vx<0?-1:1;let oldY=p.y;p.x=Math.max(0,Math.min(w.length+50,p.x+p.vx*dt));p.vy+=G*dt;p.y+=p.vy*dt;p.ground=false;
 for(const b of s.platforms){if(!overlap(p,b))continue;if(oldY+p.h<=b.y+3&&p.vy>=0){p.y=b.y-p.h;p.vy=0;p.ground=true}else if(!b.ground&&oldY>=b.y+b.h-3&&p.vy<0){p.y=b.y+b.h;p.vy=50}else if(b.ground){p.x-=p.vx*dt}}
 if(p.y>H+90){loseLife();return}
 for(const it of s.items){if(it.taken||(it.type==='heart'&&s.lives>=5))continue;if(overlap(p,{x:it.x-10,y:it.y-12,w:20,h:24})){it.taken=true;burst(it.x,it.y,it.type==='heart'?'#f4aacb':'#ffdf8c');if(it.type==='heart'){s.lives++;toast('Um coração! +1 vida');tone(760,.16);speak('Oba! Mais uma vida!')}else{s.coins++;tone(1050,.06);if(s.coins%100===0&&s.lives<5){s.lives++;toast('100 estrelas! Você ganhou uma vida!')}}}}
 for(const cp of s.checkpoints){if(!cp.active&&p.x>cp.x){cp.active=true;s.checkpoint=cp.x;burst(cp.x,cp.y-45,'#d8c3ff');toast('Bandeirinha salva! Continue brilhando.')}}
 for(const e of s.enemies){if(e.dead)continue;e.x+=e.v*dt;if(e.x<e.min||e.x>e.max)e.v*=-1;if(e.flying)e.y=e.baseY+Math.sin(s.elapsed*2.1+e.offset)*48;if(overlap(p,e)){if(p.vy>40&&oldY+p.h<e.y+15){e.dead=true;p.vy=-410;burst(e.x+15,e.y,'#c7a5df');tone(300,.09)}else hit()}}
 if(s.boss){let b=s.boss;b.inv=Math.max(0,b.inv-dt);if(p.x>w.length-680&&b.hp>0){b.fireTimer-=dt;b.casting=b.fireTimer<.55;if(b.fireTimer<=0){castShadow(b,p);b.fireTimer=b.hp<=2?2:2.7;b.casting=false}b.timer-=dt;b.warning=b.timer<.65&&b.phase===0;if(b.timer<=0){if(b.phase===0){b.phase=1;b.vy=-420;b.vx=(p.x<b.x?-1:1)*(110+(5-b.hp)*15);b.timer=.9;tone(190,.2)}else{b.phase=0;b.timer=1.8;b.vx=0}}b.x=Math.max(w.length-650,Math.min(w.length-65,b.x+b.vx*dt));b.vy+=G*dt;b.y+=b.vy*dt;if(b.y>=293){b.y=293;b.vy=0}if(overlap(p,b)){if(p.vy>35&&oldY+p.h<b.y+24&&b.inv<=0){damageBoss(1);b.inv=1;p.vy=-520;p.inv=.8;}else if(b.inv<=0)hit()}}}
 updateCombat(dt);
 for(const pt of s.particles){pt.x+=pt.vx*dt;pt.y+=pt.vy*dt;pt.vy+=300*dt;pt.life-=dt}s.particles=s.particles.filter(pt=>pt.life>0);s.camera=Math.max(0,Math.min(w.length-W+130,p.x-W*.34));if(p.x>w.length-50&&(!s.boss||s.boss.hp<=0))complete();if(Math.floor(s.elapsed*10)!==Math.floor((s.elapsed-dt)*10))updateHud();}
function enemy(c,e,t){if(e.flying){bird(c,e,t);return}const x=Math.round(e.x),y=Math.round(e.y+Math.sin(t*6)*1.5);rect(c,x+5,y,20,5,'#9270a8');rect(c,x,y+5,30,18,'#a184b8');rect(c,x+4,y+23,9,5,'#795a93');rect(c,x+18,y+23,9,5,'#795a93');rect(c,x+5,y+7,7,8,'#fff0d4');rect(c,x+19,y+7,7,8,'#fff0d4');rect(c,x+8,y+10,3,4,'#5d4169');rect(c,x+20,y+10,3,4,'#5d4169');if(e.type===1){rect(c,x+3,y-7,6,10,'#9270a8');rect(c,x+21,y-7,6,10,'#9270a8')}if(e.type===2){rect(c,x-7,y+6,7,12,'#c1a6d1');rect(c,x+30,y+6,7,12,'#c1a6d1')}}
function bird(c,e,t){const x=Math.round(e.x),y=Math.round(e.y),wing=Math.sin(t*15+e.offset)>0?-9:7;rect(c,x+5,y+4,24,18,'#9c82bd');rect(c,x+8,y,18,7,'#b49dce');rect(c,x-8,y+wing,15,8,'#c7b1df');rect(c,x+27,y+wing,15,8,'#c7b1df');rect(c,x+9,y+7,6,7,'#fff1d7');rect(c,x+22,y+7,6,7,'#fff1d7');rect(c,x+11,y+10,3,4,'#4e395e');rect(c,x+23,y+10,3,4,'#4e395e');rect(c,x+16,y+15,6,5,'#e9b779');}
function draw(){if(!state||$('#play').classList.contains('hidden'))return;const s=state,w=worlds[s.index],c=ctx; background(c,w,s.camera,s.elapsed);c.save();c.translate(-Math.round(s.camera),0);
 // Pixel scenery is deterministic and bounded to the visible camera range.
 for(const b of s.platforms){if(b.x+b.w<s.camera-20||b.x>s.camera+W+20)continue;rect(c,b.x,b.y,b.w,b.h,w.earth);rect(c,b.x,b.y,b.w,9,w.grass);rect(c,b.x,b.y+9,b.w,4,'#ffffff35');for(let j=12;j<b.w;j+=25){rect(c,b.x+j,b.y+22+(j%4)*5,7,5,'#ffffff20')}if(b.ground){for(let xx=b.x+24;xx<b.x+b.w-10;xx+=95){if(xx>s.camera-15&&xx<s.camera+W+15)flower(c,xx,b.y,w.accent)}}else{rect(c,b.x+6,b.y+b.h,b.w-12,4,'#ffffff33');star(c,b.x+b.w/2,b.y+10,4,'#fff5d7')}}
 for(const cp of s.checkpoints){rect(c,cp.x,cp.y-65,4,65,'#f6ebdf');rect(c,cp.x+4,cp.y-65,28,20,cp.active?'#f7d58c':'#bea2cf');star(c,cp.x+16,cp.y-55,6,'#fff6dd')}
 for(const it of s.items){if(it.taken||it.x<s.camera-25||it.x>s.camera+W+25)continue;let yy=it.y+Math.sin(s.elapsed*3+it.x)*3;if(it.type==='heart')heart(c,it.x-10,yy-7,3);else{star(c,it.x,yy,10,'#c79d60');star(c,it.x,yy-2,8,'#ffe59b');rect(c,it.x-2,yy-6,2,3,'#fff9d7')}}
 s.enemies.forEach(e=>{if(!e.dead&&e.x>s.camera-40&&e.x<s.camera+W+40)enemy(c,e,s.elapsed)});
 for(const f of s.flowers){c.save();c.translate(f.x+8,f.y+8);c.rotate(s.elapsed*10);for(let i=0;i<4;i++){c.rotate(Math.PI/2);rect(c,-4,-12,8,9,'#f397c4')}rect(c,-4,-4,8,8,'#ffe49a');c.restore()}
 for(const shot of s.darkShots){rect(c,shot.x-3,shot.y+4,22,8,'#d3a6ec66');star(c,shot.x+8,shot.y+8,11,'#76539e');star(c,shot.x+8,shot.y+8,6,'#dbb7ef')}
 const portalX=w.length-10;rect(c,portalX-12,270,56,95,'#d8bbdf');rect(c,portalX-22,285,76,80,'#cfb1dc');rect(c,portalX-4,285,40,80,'#9d80b9');rect(c,portalX+3,295,26,70,'#efccf0');star(c,portalX+16,263,18,'#ffe59c');for(let i=0;i<4;i++)star(c,portalX-28+i*27,240+Math.sin(s.elapsed*2+i)*12,4,'#fff4c4');
 if(s.boss&&s.boss.hp>0){let b=s.boss;if(!(b.inv>0&&Math.floor(s.elapsed*15)%2)){let x=b.x,y=b.y;c.fillStyle=b.warning?'#e5acd0':'#8e74a8';rect(c,x+8,y+5,48,55,c.fillStyle);rect(c,x,y+20,64,42,c.fillStyle);rect(c,x+4,y-5,13,22,'#79618f');rect(c,x+48,y-5,13,22,'#79618f');rect(c,x+7,y+62,18,10,'#6f568a');rect(c,x+40,y+62,18,10,'#6f568a');rect(c,x+12,y+24,14,16,'#fff0cf');rect(c,x+39,y+24,14,16,'#fff0cf');rect(c,x+16,y+31,6,8,'#584065');rect(c,x+42,y+31,6,8,'#584065');rect(c,x+28,y+48,10,5,'#efbfda');star(c,x+32,y+5,11,'#ffdf94');if(b.casting){star(c,x-8,y+34,14+Math.sin(s.elapsed*25)*3,'#eed0ff');star(c,x+72,y+34,14+Math.sin(s.elapsed*25)*3,'#eed0ff')}if(b.warning||b.casting){c.font='bold 22px sans-serif';c.fillStyle='#fff3be';c.fillText('!',x+29,y-22)}}}
 if(!(s.p.inv>0&&Math.floor(s.elapsed*12)%2))girl(c,s.p.x-10,s.p.y-4,3,character,s.p.ground&&s.p.vx?s.elapsed*18:0,s.p.face<0);
 for(const pt of s.particles)rect(c,pt.x,pt.y,4,4,pt.color);c.restore();}
function frame(time){pollGamepad();music();const delta=Math.min((time-rafTime)/1000||0,1/15);rafTime=time;accum+=delta;let loops=0;while(accum>=1/60&&loops<4){step(1/60);accum-=1/60;loops++}if(loops===4)accum=0;if(mode==='play'||mode==='paused')draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
